const initial=[{id:'title',kind:'heading',title:'Opening',text:'A little time. Deeper roots.',x:5,y:12,w:85},{id:'reflection',kind:'paragraph',title:'Reflection',text:'Jesus names himself as the vine. Our first invitation is to remain close to him, receiving the life we cannot create on our own.',x:6,y:47,w:39},{id:'connection',kind:'diagram',title:'A living connection',text:'Remain in Christ; receive his words; bear fruit in everyday life.',x:51,y:47,w:45},{id:'question',kind:'paragraph',title:'A question to carry',text:'What might help you make a little room for his words today?',x:6,y:82,w:88}];
let blocks=structuredClone(initial),undo=[],dirty=false;try{const b=JSON.parse(sessionStorage.getItem('rooted-doc-v2'));if(Array.isArray(b)&&b.length)blocks=b}catch{}
