try{const s=JSON.parse(sessionStorage.getItem('rooted-sources-v2'));if(Array.isArray(s))sources=s}catch{}if(state==='empty')sources=[];
let detailId='s1',selectionRange=null;const persist=()=>{sessionStorage.setItem('rooted-doc-v2',JSON.stringify(blocks));dirty=true},saveSources=()=>sessionStorage.setItem('rooted-sources-v2',JSON.stringify(sources)),chosen=()=>sources.filter(s=>s.status==='ready'&&s.selected),announce=t=>document.querySelector('#announcement').textContent=t;
