const sprout='<svg viewBox="0 0 32 36" aria-hidden="true"><path d="M16 34V17C4 17 2 7 2 7c12-2 14 10 14 10C16 5 25 1 30 2c0 12-14 15-14 15" fill="currentColor"/></svg>';
const href=(v,s='ready',extra='')=>`?view=${v}&state=${s}&church=${church}${extra}`,link=(v,t,c='',s='ready',extra='')=>`<a class="${c}" href="${href(v,s,extra)}">${t}</a>`,brand=()=>`<a class="brand" href="?view=board" aria-label="Rooted research home">${sprout}Rooted</a>`;
const research=()=>'<div class="research"><span>PRODUCT EXPERIENCE REBUILD · NOV 1, 2026 <span class="extra">/ Fictional Grace Church / Simulated extraction and AI</span></span><a href="?view=board">Research concept</a></div>';
function header(){return `<header class="topbar">${brand()}<nav class="toplinks" aria-label="Research workspace">${[['library','Sources'],['studio','Studio / Compose'],['review','Review'],['deck','Share']].map(([v,t])=>`<a href="${href(v)}" ${view===v?'aria-current="page"':''}>${t}</a>`).join('')}<span class="avatar">AM</span></nav></header>`}
function shell(content){return `${research()}${header()}<div class="workspace"><aside class="rail"><p class="church">Grace<br>Community Church</p><p class="eyebrow">ABIDE IN CHRIST</p>${[['library','▤ Channel sources'],['studio','▧ Studio / Compose'],['review','◷ Review conversation'],['deck','↗ Public share deck'],['qr','▣ Member access']].map(([v,t])=>link(v,t,view===v?'active':'')).join('')}<div class="bottom">Your church’s teaching.<br>A shared direction.</div></aside><main id="main" tabindex="-1" class="main"><div class="context"><div><p class="eyebrow">ABIDE IN CHRIST / MONDAY · NOV 2 · AMERICA/NEW_YORK</p><h1>A little time. Deeper roots.</h1><div class="meta"><span>Study draft r12</span><span id="save-state">${dirty?'Research changes in this browser':'Saved research fixture'}</span><span class="pill warn">1 change request</span></div></div><div class="actions">${link('preview','Preview ↗','button')}<button data-action="save" class="primary">Save draft</button></div></div><div class="review-strip"><p><strong>Morgan requested a clearer connection to John 15:5.</strong> &nbsp; Reflection · r11.</p>${link('review','Open conversation →')}</div>${content}</main></div>`}
function diagram(){return '<svg class="diagram" viewBox="0 0 600 155" role="img" aria-label="Illustrative teaching flow: remain in Christ, receive his words, and bear fruit. Not measured data."><path d="M180 75h40m160 0h40" stroke="#217360" stroke-width="2"/><rect y="15" width="180" height="120" rx="11" fill="#e3eadc"/><rect x="210" y="15" width="180" height="120" rx="11" fill="#efe1ce"/><rect x="420" y="15" width="180" height="120" rx="11" fill="#e8e0ed"/><g font-family="Georgia" font-size="27" text-anchor="middle" fill="#17363f"><text x="90" y="70">Remain</text><text x="300" y="70">Receive</text><text x="510" y="70">Bear fruit</text></g><g font-family="Segoe UI" font-size="12" text-anchor="middle" fill="#52696b"><text x="90" y="100">Stay close to Christ</text><text x="300" y="100">Return to his words</text><text x="510" y="100">Live one next step</text></g></svg>'}
const pill=s=>`<span class="pill ${s.status==='error'?'error':s.status==='processing'?'warn':''}">${s.status==='processing'?'<i class="spinner"></i> ':''}${s.status==='ready'?'Ready':s.status==='error'?'Needs attention':'Processing'}</span>`;
function library(){const d=sources.find(s=>s.id===detailId)||sources[0];return shell(`<div class="section-head"><div><p class="eyebrow">CHANNEL SOURCE LIBRARY</p><h2>Keep the teaching together.</h2><p>Import once. Choose ready sources for the assistant to use in this study.</p></div><button class="primary" data-action="import">＋ Import</button></div><div class="library-layout"><section class="panel" style="padding:0;overflow:hidden"><div class="library-toolbar"><label class="search"><span>⌕</span><input id="source-search" aria-label="Search channel sources" placeholder="Search sources" type="search"></label><span class="fine">${sources.length} sources · ${chosen().length} selected</span></div>${sources.length?`<table class="source-table"><thead><tr><th><span class="sr-only">Use in context</span></th><th>Source name</th><th>Processing</th><th>Added</th></tr></thead><tbody>${sources.map(s=>`<tr data-source-row="${s.id}" class="${s.selected?'selected':''}"><td><input type="checkbox" data-context="${s.id}" aria-label="Use ${esc(s.name)} in assistant context" ${s.selected?'checked':''} ${s.status!=='ready'?'disabled':''}></td><td><div class="source-name"><span class="filemark ${s.type.toLowerCase()}">${s.type}</span><div><button data-detail="${s.id}" style="border:0;background:none;padding:0;min-height:24px;text-align:left"><strong>${esc(s.name)}</strong></button>${s.url?`<p class="source-link">${esc(s.url)}</p>`:`<p>${s.version} · ${esc(s.locator||'pending')}</p>`}</div></div></td><td>${pill(s)}</td><td class="fine">Today<br>Anna Martin</td></tr>`).join('')}</tbody></table>`:'<div class="empty"><p class="eyebrow">THIS CHANNEL’S TEACHING BASIS</p><h2>A source library,<br>ready for your church.</h2><p>Documents, links, notes, and approved connections belong here. Use Import above to begin.</p></div>'}<div style="padding:16px 18px;border-top:1px solid var(--line)"><p class="fine">SELECTED FOR THIS STUDY · NOT SENT TO AI</p><div class="context-chips">${chosen().map(s=>`<span class="context-chip">${esc(s.name)} · ${s.version}</span>`).join('')||'<span class="fine">No sources selected.</span>'}</div></div></section><aside class="panel source-detail">${d?`<div class="between"><p class="eyebrow">SOURCE DETAILS</p>${pill(d)}</div><h3>${esc(d.name)}</h3><div class="detail"><strong>Context snapshot</strong>${d.version} · ${esc(d.locator||'pending')}</div><div class="detail"><strong>${d.status==='ready'?'What is available':'What needs attention'}</strong>${esc(d.detail||'Processing source fixture.')}</div>${d.text?`<div class="detail"><strong>Indexed sample excerpt</strong>“${esc(d.text)}”</div>`:''}<p class="fine gap">Ready means sample extraction/indexing finished. It does not certify teaching accuracy, rights, or Scripture references.</p>${d.status==='error'?'<button class="gap" data-action="retry-source">Provide a transcript instead</button>':''}<div class="rule"><p class="eyebrow">DRAFT CONTEXT IS PINNED</p><p class="fine">Refresh or removal does not silently change source snapshots already used in a draft.</p></div>`:'<h3>One library. Many studies.</h3><p class="fine gap">Names, extraction state, versions, and locators stay with the teaching basis.</p>'}</aside></div><p class="workflow-status" id="workflow-status" role="status">Ready selections appear beside the assistant in Studio; processing and failed items stay out.</p>`)}
function importBody(){if(importKind==='files')return `<div class="dropzone" id="dropzone"><strong>Drop your sources here.</strong><p class="small">Keep original filenames in the channel library.</p><button class="gap" data-action="choose-files">Choose files</button><input id="file-picker" type="file" multiple hidden><div class="type-list">${['PDF','DOCX / ODT / RTF','PPTX','XLSX / CSV','TXT / MD','Audio','Images'].map(t=>`<span>${t}</span>`).join('')}</div></div><div class="capabilities">${[['PDF & documents','PDF · DOCX · ODT · RTF','Parser / OCR planned'],['Presentations & spreadsheets','PPTX · CSV · XLSX','Structured extraction planned'],['Text & notes','TXT · MD · pasted text','Local text fixture available'],['Audio & images','MP3 · WAV · PNG · JPG','Transcription / OCR planned']].map(([a,b,c])=>`<div><strong>${a}</strong><p class="fine">${b}</p><span class="pill ${c.includes('planned')?'planned':''}">${c}</span></div>`).join('')}</div><p class="fine gap">Chosen real files keep their names but remain unprocessed here. Use the sample batch to demonstrate completion and partial failure.</p>`;if(importKind==='links')return '<label class="field">Website or YouTube URLs · one per line<textarea id="link-input" placeholder="https://your-church.example/sermon-notes"></textarea></label><div class="capabilities"><div><strong>Public website</strong><span class="pill planned">Approved-host fetch planned</span><p class="fine gap">No private page or sign-in bypass.</p></div><div><strong>YouTube</strong><span class="pill warn">Channel permission required</span><p class="fine gap">Authorized captions or a supplied transcript, not arbitrary video analysis.</p></div></div><button class="gap" data-action="add-links">Add link names to library</button>';if(importKind==='paste')return '<label class="field">Source title<input id="paste-title" value="Pastor’s teaching notes"></label><label class="field">Text or Markdown<textarea id="paste-text" placeholder="Paste the teaching text you have permission to use…"></textarea></label><button class="gap" data-action="add-paste">Add pasted source</button><p class="fine gap">Stays in this research session. No AI request.</p>';return `${[['Google Drive','Docs · Slides · Sheets'],['Microsoft OneDrive','Word · PowerPoint · Excel'],['Dropbox','Church-approved files']].map(([a,b])=>`<div class="panel gap" style="padding:16px"><div class="between"><strong class="small">${a}</strong><span class="pill planned">Planned · not connected</span></div><p class="fine gap">${b}</p><p class="fine">Church authorization, file permission, visible source version, and a refresh policy are required.</p></div>`).join('')}`}
function openImport(){const d=document.querySelector('#import-dialog');d.innerHTML=`<div class="dialog-head"><div><p class="eyebrow">ADD TO ABIDE IN CHRIST / CHANNEL</p><h2 id="import-title">Import sources.</h2><p class="fine gap">One place for the material behind your teaching.</p></div><button data-action="close-import" aria-label="Close import dialog">×</button></div><div class="dialog-body"><div class="import-tabs" role="group" aria-label="Import method">${[['files','Files'],['links','Links'],['paste','Paste text'],['connections','Connections']].map(([v,t])=>`<button data-import-kind="${v}" aria-pressed="${v===importKind}">${t}</button>`).join('')}</div>${importBody()}</div><div class="dialog-foot"><p class="fine">Capability labels describe this concept.<br>No provider connection or upload runs.</p><button class="primary" data-action="sample-batch">Add sample batch →</button></div>`;bindDialog();if(!d.open)d.showModal();d.querySelector(`[data-import-kind="${importKind}"]`).focus()}
function addSamples(){for(const s of [{id:'batch-doc',name:'Sunday service transcript.txt',type:'TXT',status:'processing',selected:false,version:'v1',locator:'pending'},{id:'batch-slides',name:'Abide teaching slides.pptx',type:'PPTX',status:'processing',selected:false,version:'v1',locator:'pending'},{id:'batch-video',name:'https://youtube.com/watch?v=grace-sample',url:'https://youtube.com/watch?v=grace-sample',type:'YT',status:'processing',selected:false,version:'v1',locator:'pending'}])if(!sources.some(x=>x.id===s.id))sources.push(s);saveSources();document.querySelector('#import-dialog').close();render();setTimeout(()=>{sources=sources.map(s=>s.id==='batch-doc'?{...s,status:'ready',locator:'lines 1–45',text:'Remain in Christ and return to his words.',detail:'Sample text fixture indexed; original filename retained.'}:s.id==='batch-slides'?{...s,status:'ready',locator:'slides 2–5 / notes',text:'One church, a shared direction.',detail:'Presentation fixture indexed. Text/notes only, layout needs review.'}:s.id==='batch-video'?{...s,status:'error',detail:'Channel permission is missing; provide authorized captions or a transcript.'}:s);saveSources();render();status('Sample batch: two ready, one needs permission. No real extraction ran.')},1800)}
function visual(b){if(b.kind==='diagram')return diagram();if(b.kind==='image')return '<svg viewBox="0 0 500 160" role="img" aria-label="Original placeholder vine illustration, not a generated photograph" style="width:100%;display:block"><rect width="500" height="160" rx="8" fill="#dfe8d8"/><circle cx="400" cy="45" r="25" fill="#eadfa4"/><path d="M160 150C185 40 270 100 310 12" fill="none" stroke="#34745c" stroke-width="5"/><path d="M191 105c-60 4-65-44-48-64 45 0 64 31 48 64m37-25c-2-50 39-62 65-54 0 38-24 59-65 54" fill="#78a186"/></svg>';if(b.kind==='chart')return '<div><svg viewBox="0 0 500 160" role="img" aria-label="Illustrative invitations: one each on Monday, Wednesday, Friday, Saturday" style="width:100%;height:130px"><g fill="#217360"><rect x="40" y="35" width="65" height="90"/><rect x="155" y="35" width="65" height="90"/><rect x="270" y="35" width="65" height="90"/><rect x="385" y="35" width="65" height="90"/></g><g font-size="13" font-family="Segoe UI" fill="#17363f" text-anchor="middle"><text x="72" y="151">Mon</text><text x="187" y="151">Wed</text><text x="302" y="151">Fri</text><text x="417" y="151">Sat</text></g></svg><details><summary class="fine">Accessible chart data</summary><table class="chart-table"><tr><th>Day</th><th>Scheduled invitations</th></tr><tr><td>Mon, Wed, Fri, Sat</td><td>1 each · illustrative</td></tr></table></details></div>';if(b.kind==='video')return '<div class="note"><strong>Video block · media not attached</strong><p class="fine gap">A reviewed asset needs captions, transcript, poster, and rights. Reading has a text alternative; no autoplay.</p></div>';return ''}
function marks(b){const m=(b.marks||[]).find(m=>['strong','em'].includes(m.tag)&&Number.isInteger(m.start)&&Number.isInteger(m.end)&&m.start>=0&&m.end<=b.text.length&&m.end>m.start);return m?esc(b.text.slice(0,m.start))+'<'+m.tag+'>'+esc(b.text.slice(m.start,m.end))+'</'+m.tag+'>'+esc(b.text.slice(m.end)):esc(b.text)}
function blockContent(b,reading=false){const style=`${b.bold?'font-weight:700;':''}${b.italic?'font-style:italic;':''}${b.align?`text-align:${b.align};`:''}${b.size?`font-size:${b.size}px;`:''}`,edit=reading?'':`contenteditable="true" data-edit="${b.id}" role="textbox" aria-label="Edit ${b.title}"`;if(['diagram','image','chart','video'].includes(b.kind))return `${visual(b)}${reading?`<p class="fine" style="font:11px/1.6 'Segoe UI'">${esc(b.text)}</p>`:''}`;if(b.kind==='heading')return reading?`<h1 style="${style}">${marks(b)}</h1>`:`<h2 ${edit} style="${style}">${marks(b)}</h2>`;if(b.kind==='columns')return `<div class="column-content"><p ${edit} style="${style}">${marks(b)}</p><p>A passage to read. A question to carry. One practical response.</p></div>`;return `<p ${edit} style="${style}">${marks(b)}</p>`}
function editorCanvas(){return `<div class="${mode==='design'?'artboard':'page'}" id="document-canvas"><p class="doc-sub">GRACE COMMUNITY CHURCH / JOHN 15:1–8</p>${blocks.map((b,i)=>`<section data-block="${b.id}" class="block ${selected===b.id?'selected':''}" tabindex="0" role="group" aria-label="${esc(b.title)}, reading position ${i+1}" ${mode==='design'?`style="left:${b.x||5}%;top:${b.y||10}%;width:${b.w||75}%;z-index:${b.z||i+1}"`:''}><div class="block-label"><span>${esc(b.title)}</span><span>READ ${i+1}</span></div>${blockContent(b)}</section>`).join('')}</div>`}
function assistant(){return `<aside class="assistant"><div class="assistant-head"><span class="avatar">✦</span><div><h2>Studio assistant</h2><p class="fine">Writing + visuals · one conversation</p></div><a class="button" href="#current-proposal">Review proposed change ↓</a></div><div class="assistant-body"><div class="assistant-context"><strong>${chosen().length} sources selected for context</strong>${chosen().map(s=>`<div style="margin-top:5px">${esc(s.name)}<br><span class="fine">${s.version} · ${esc(s.locator)}</span></div>`).join('')||'<p>No source selected.</p>'}${link('library','Manage channel sources →')}</div><div class="chat-user">Help connect this reflection to John 15:5. Keep the invitation welcoming.</div><div class="chat-response"><p>I can revise the current selection while keeping the rest of your study.</p><div class="proposal" id="current-proposal" tabindex="-1"><span class="eyebrow">PROPOSED REPLACEMENT / SELECTION</span><p id="proposal-text">Remaining close to Christ comes before our response. His life is the source of the fruit we cannot produce on our own.</p><p class="fine" style="font:10px/1.5 'Segoe UI'">Sample request context: ${chosen().map(s=>esc(s.name)+' · '+s.version+' · '+esc(s.locator)).join('; ')||'No source selected; no source-backed proposal available.'}</p><button class="primary" data-action="apply" ${chosen().length?'':'disabled'}>Apply to selection</button></div></div><label class="field">Ask about the current selection<textarea id="assistant-input" placeholder="Write, explain, design, or refine…"></textarea></label><div class="sendrow"><span>Sample assistant · no live AI</span><button data-action="ask">Preview response ↗</button></div></div></aside>`}
function studio(){const b=blocks.find(b=>b.id===selected)||blocks[0];selected=b.id;return shell(`<div class="studio-topline"><div><p class="eyebrow">STUDIO / COMPOSE</p><p class="fine">Write, design, and ask for help in the same workspace.</p></div><div class="segmented" role="group" aria-label="Canvas mode"><button data-mode="reading" aria-pressed="${mode==='reading'}">Write / reading page</button><button data-mode="design" aria-pressed="${mode==='design'}">Design / artboard</button></div></div><div class="studio-workspace"><section class="editor"><div class="ribbon" role="toolbar" aria-label="Compose ribbon"><div class="group"><select id="font-size" aria-label="Selected text size"><option value="18">Body · 18</option><option value="22">Large · 22</option><option value="28">Heading · 28</option></select><button class="letter" data-format="bold" aria-label="Bold selection" aria-pressed="${!!b.bold}"><b>B</b></button><button class="letter" data-format="italic" aria-label="Italic selection" aria-pressed="${!!b.italic}"><i>I</i></button></div><div class="group"><button data-align="left" aria-label="Align selected block left">≡</button><button data-align="center" aria-label="Center selected block">☰</button></div><div class="group"><select id="insert-kind" aria-label="Insert content">${['paragraph','image','video','diagram','chart','columns'].map(k=>`<option value="${k}">${k==='paragraph'?'Text':k[0].toUpperCase()+k.slice(1)}</option>`).join('')}</select><button class="insert" data-action="insert">＋ Insert</button></div><div class="group"><button data-action="undo" ${undo.length?'':'disabled'}>↶ Undo</button></div></div><div class="contextual"><span id="selection-label">Selected: <strong>${esc(b.title)}</strong> · Reading position ${blocks.indexOf(b)+1}</span><select id="block-outline" aria-label="Document outline and selected block">${blocks.map(x=>`<option value="${x.id}" ${x.id===selected?'selected':''}>${esc(x.title)}</option>`).join('')}</select><button data-action="up">↑ Move up</button><button data-action="down">↓ Move down</button><button data-action="describe">Text alternative</button></div><div class="canvas-stage">${editorCanvas()}</div>${mode==='design'?`<div class="placement"><label>X % <input type="number" min="0" max="85" data-place="x" value="${b.x||5}"></label><label>Y % <input type="number" min="0" max="85" data-place="y" value="${b.y||10}"></label><label>Width % <input type="number" min="10" max="95" data-place="w" value="${b.w||75}"></label><button data-action="front">Bring forward</button><button data-action="crop">Crop preview</button><span class="fine">Placement and layers do not change reading order. Grouping / full image crop are planned.</span></div>`:''}<div class="editor-footer"><span>${blocks.length} logical blocks · ${mode==='design'?'Artboard geometry':'Reflowing reading page'} · Draft r12</span><div class="row">${link('preview','Immersive preview ↗','button')}<button class="primary" data-action="save">Save draft</button></div></div></section>${assistant()}</div><p class="workflow-status" id="workflow-status" role="status">Selected content and source snapshots stay visible. Research editing only.</p>`)}
function readingBlocks(){return blocks.map((b,i)=>`<section class="reader-block" data-reading-block="${b.id}" ${b.id==='reflection'?'id="member-reflection" tabindex="-1"':''}><p class="eyebrow">${i+1} / ${esc(b.title)}</p>${blockContent(b,true)}</section>`).join('')}
function preview(){return `${research()}<header class="previewbar"><div><strong>Immersive reading preview</strong><p class="fine">Draft r12 · same content and logical order as Studio · unpublished</p></div>${link('studio','← Back to Studio','button')}</header><main id="main" class="reading" tabindex="-1"><p class="eyebrow">GRACE COMMUNITY CHURCH · NOVEMBER 2</p><p>John 15:1–8 · Read the passage in your Bible.</p>${readingBlocks()}<p class="fine gap">Artboard geometry never determines reading order. Production publishes an approved snapshot through its supported block renderer.</p></main>`}
function review(){return shell(`<div class="section-head"><div><p class="eyebrow">REVIEW CONVERSATION</p><h2>The reason stays with the revision.</h2><p>A reply records the response; an authorized reviewer resolves the request.</p></div><span class="pill warn">1 unresolved</span></div><div class="thread-layout"><section class="panel"><div class="pinned"><p class="eyebrow">MORGAN LEE / APPROVER / REQUEST ON R11</p><h3>Ground the reflection in John 15:5.</h3><p>Show dependence on Christ before inviting the action. It currently reads like self-improvement.</p><a href="#revision-note" class="button gap">Reflection · r11 · View quoted anchor →</a></div><div class="message"><p class="byline">Anna Martin · Submission note · Oct 31, 9:42 AM</p><p>Please check whether the invitation welcomes readers who are new to the Bible.</p></div><div class="message"><p class="byline">Morgan Lee · Changes requested · Oct 31, 10:14 AM</p><p>Keep it short, but begin with Christ as the source of growth. This note stays on the original revision if content drifts.</p></div><label class="field">Reply with what changed<textarea id="review-reply">I made the practical step a response to Christ’s care.</textarea></label><button class="primary gap" data-action="review-reply">Add reply to conversation</button><p class="fine gap" id="review-status" role="status">Current draft r12. Replying does not approve or resolve it.</p></section><aside class="panel" id="revision-note" tabindex="-1"><p class="eyebrow">QUOTED ANCHOR / REFLECTION / R11</p><h3>“Make a better habit and see what grows.”</h3><div class="rule"><p class="eyebrow">CURRENT DRAFT / REFLECTION / R12</p><p>${esc(blocks.find(b=>b.id==='reflection')?.text||'Reflection was removed from this draft; original anchor retained.')}</p></div><div class="note gap">A fresh review cycle may target the same unchanged revision. No meaningless edit is required. Approval stays tied to an exact revision.</div><p class="fine gap">The current API’s retry defect needs engineering work. Preserve reply/history and show recovery; this prototype sends no review request.</p></aside></div><div class="thread-actions"><p class="fine">Original request r11 remains open.<br>Independent reviewer required</p><div class="row">${link('studio','Edit and ask in Studio →','button')}<button data-action="review-resubmit" class="primary">Preview fresh review cycle</button></div></div>`)}
const deckCopy=[['A little time.','Deeper roots.'],['Remain in Christ.','Receive his words.'],['A question to carry.','What helps you stay close?'],['A faithful response.','Live one next step.']];
function deckCard(n=slide){const c=deckCopy[n-1];return `<div class="deck-slide" id="deck-export"><span class="deck-logo">GRACE COMMUNITY CHURCH</span><h2>${c[0]}<br><em>${c[1]}</em></h2><p>${n===1?'A shared invitation to John 15:1–8.':n===2?'Our connection to Christ comes before our action.':n===3?'Read the passage, pause, and consider an honest answer.':'Make a little room for Scripture in the ordinary day.'}</p><div class="co-brand"><span>GRACE CHURCH · 0${n}/04</span><b>Rooted ↗</b></div></div>`}
const thumbs=()=>`<div class="thumbs" role="group" aria-label="Choose a deck card">${[1,2,3,4].map(n=>`<button data-slide="${n}" aria-pressed="${slide===n}">0${n}</button>`).join('')}</div>`;
function deck(){return shell(`<div class="section-head"><div><p class="eyebrow">PUBLIC SHARE DECK / SEPARATE APPROVAL</p><h2>An invitation that can travel.</h2><p>Cards, caption, branding, and public destination form one reviewed rendition.</p></div><span class="pill ${state==='stale'?'warn':''}">${state==='stale'?'Changed source · not exportable':state==='approval'?'Approver example':'Draft excerpt'}</span></div><div class="deck-layout"><div class="deck-stage">${deckCard()}${thumbs()}</div><section class="panel"><p class="eyebrow">GRACE CHURCH + ROOTED</p><h3>Public excerpt · deck v3</h3><label class="field">Public caption<textarea readonly>A little time in Scripture gives the week a shared direction. Read John 15:1–8 with Grace Church.</textarea></label><div class="note ${state==='stale'?'warning':''} gap">${state==='stale'?'Preview case: selecting a new source revision marks this rendition stale. Future export/share waits for review. Downloaded copies cannot be recalled.':state==='approval'?'Reviewer example: approved source r10, deck v3, exact cards + caption + public invitation. Current draft r12 is not the public source.':'Current study r12 has changes requested. Prepare the deck here; public approval waits for an approved source.'}</div><div class="actions gap">${state==='approval'?'<button data-action="approve-deck" class="primary">Simulate rendition approval</button>':link('deck','Preview approved-source case →','button','approval')}${link('share','Member opt-in preview →')}</div><p class="fine gap" id="deck-status" role="status">No private reflections, source-library material, member names, or reading activity enter this public deck.</p></section></div>`)}
function churchContext(){return `<div class="church-context"><span class="mark">G</span><div><strong>Grace Community Church</strong><p>${church==='north'?'Salem · North gathering':'Portland · Main gathering'}</p></div></div>`}
function phoneShell(c){return `<div class="phone"><div class="phonebar">REBUILT RESEARCH CONCEPT · No SMS, account, or church record changed.</div><header>${brand()}<span class="fine">Grace Church</span></header><main id="main" tabindex="-1">${c}</main><footer class="phone-footer"><span>Rooted in Scripture.</span>${link('board','Research storyboard')}</footer></div>`}
function phone(){let c='';if(state==='ambiguity')c=`<p class="eyebrow">CONFIRM THE CHURCH</p><h1>Which Grace Church?</h1><p class="intro">Choose the right reading space before continuing.</p>${[['main','Portland · Main gathering'],['north','Salem · North gathering']].map(([id,t])=>`<button class="phone-option" data-church="${id}" aria-pressed="${church===id}"><strong>Grace Community Church</strong><span>${t}</span></button>`).join('')}<button class="primary wide" data-phone="ready">Continue with selected church →</button>`;else if(state==='verify'||state==='expired')c=`<p class="eyebrow">VERIFY YOUR IDENTITY</p>${churchContext()}<h1>Check your phone.</h1><p class="intro">Sample number ending 0104. The church stays selected.</p><label class="field">Fictional code<input value="123456" readonly style="letter-spacing:10px;text-align:center;font-size:23px"></label>${state==='expired'?'<div class="note warning gap">This sample code expired. Replace it without losing your church.</div>':''}<button class="primary wide" data-phone="${state==='expired'?'verify':'name'}">${state==='expired'?'Preview replacement code':'Use the sample code →'}</button><button class="wide" data-phone="ready">Change phone / use another method</button><p class="fine">Phone-first authentication needs a provider decision. A name is never a credential.</p>`;else if(state==='name')c=`<p class="eyebrow">CONFIRM YOUR PROFILE</p><h1>Welcome, Riley.</h1>${churchContext()}<label class="field">Display name<input value="Riley Morgan" readonly></label><div class="note gap">Shared or reassigned phones never merge people or grant roles silently.</div><button class="primary wide" data-phone="enroll">Continue as Riley →</button><button class="wide" data-phone="conflict">This isn’t me</button>`;else if(state==='conflict')c='<p class="eyebrow">KEEP THE RIGHT ACCOUNT</p><h1>A shared number needs care.</h1><p class="intro">Use an existing verified sign-in or ask the church for help. We will not merge another person’s account.</p><div class="note">Church choice stays in place. Recovery needs its own identity check.</div><button class="primary wide" data-phone="ready">Return to sign-in options →</button>';else if(state==='enroll'||state==='pending')c=`<p class="eyebrow">MEMBER READING ACCESS</p><h1>${state==='pending'?'Your request is with the church.':'Read with your church.'}</h1>${churchContext()}<p class="intro">${state==='pending'?'This church reviews reading requests. Private studies open after approval.':'This church link allows verified readers to enroll. Continue as Riley Morgan.'}</p><div class="note">Reading access is separate from formal membership, contributor access, and administrator permissions.</div>${state==='pending'?'':'<label class="checkbox gap"><input type="checkbox" id="reminders"><span>Optional study reminders. I can change this later.</span></label><button class="primary wide" data-phone="complete">Join the reading space →</button>'}<p class="fine">Church policy controls enrollment. Planning Center matching remains future admin-controlled work.</p>`;else if(state==='complete')c=`<p class="eyebrow">YOUR NEXT STUDY</p><h1>A little time.<br>Room to grow.</h1>${churchContext()}<span class="pill">Member reader only · concept</span><section class="panel gap"><h2>A little time. Deeper roots.</h2><p class="fine gap">John 15:1–8 · Monday</p>${link('reader','Read the study →','button primary gap')}${link('share','Optional share preview →','button gap')}</section>`;else c=`<p class="eyebrow">YOUR CHURCH. YOUR WEEK.</p><h1>A familiar place.<br>A simple way in.</h1><p class="intro">Your church link brought you here. Sign in to read with your people.</p>${churchContext()}<label class="field">Phone · fictional sample<input value="+1 (202) 555-0104" readonly></label><button class="primary wide" data-phone="verify">Preview verification →</button><button class="wide" data-action="alternate">Use another sign-in method</button><p class="fine" id="phone-status">Phone-first login is a proposed architecture. No SMS is sent.</p><div class="rule">${link('phone','This isn’t my church →','','ambiguity')}<p class="fine">No marketing or social sharing is enabled by sign-in.</p></div>`;return phoneShell(c)}
function reader(){return phoneShell(`<div class="reading"><p class="eyebrow">MEMBER RENDITION PREVIEW / DRAFT R12</p><p>John 15:1–8 · ${church==='north'?'Salem':'Portland'} · Not published</p>${readingBlocks()}<p class="fine gap">Same edited content and logical order as Studio. Actual members get the approved published snapshot, isolated from draft changes.</p>${link('share','Optional: share a public invitation →','button gap')}</div>`)}
function share(){return phoneShell(`<p class="eyebrow">AN INVITATION, IF YOU’D LIKE</p><h1>A thought to carry.<br>Or to share.</h1><p class="intro">An approved public excerpt from source r10. Private studies remain protected.</p><span class="pill">Public deck v3 · approved source r10</span><div class="gap">${deckCard()}${thumbs()}</div><section class="share-options"><h3>Preview what travels.</h3><p class="small gap">Four cards, both brands, public caption, and invitation. No private notes, sources, or member data.</p><p class="small gap"><strong>Anyone can forward shared or downloaded cards. Copies cannot be recalled.</strong></p><label class="checkbox gap"><input id="share-consent" type="checkbox"><span>Show me sharing options for this public invitation.</span></label><button class="primary wide" data-action="share" disabled>Preview share options →</button><div id="share-options" hidden><div class="note gap">No account connected. Nothing posted. Copy link / download are fallbacks.</div><div class="row gap"><button data-action="copy">Copy public link</button><button data-action="download">Download preview</button></div></div><p class="fine" id="share-status" role="status">Sharing is optional. All four cards stay in approved order.</p></section><a class="button wide" href="${href('reader')}#member-reflection">Cancel & return to reflection →</a>`)}
function qr(){return shell(`<div class="section-head"><div><p class="eyebrow">CHURCH LINK / MEMBER ACCESS</p><h2>The right church, from the first step.</h2><p>Keep context through verification and reading enrollment.</p></div></div><div class="qr-layout"><div class="qr-hero"><p class="eyebrow" style="color:#dce8b4">GRACE COMMUNITY CHURCH</p><h2>Let Sunday take root.<br>All week long.</h2><p>The church link routes readers, never grants team access.</p><p class="fine gap" style="color:#dce6d5">Future Planning Center People matching needs admin authorization, uncertain-match review, and an explicit policy.</p></div><section class="panel" style="text-align:center"><h3>Read with Grace Church.</h3><svg class="qr-pattern" viewBox="0 0 100 100" aria-label="Illustrative non-scannable QR pattern" role="img"><rect width="100" height="100" fill="white"/><g fill="#17363f"><path d="M5 5h30v30H5zm5 5v20h20V10zM65 5h30v30H65zm5 5v20h20V10zM5 65h30v30H5zm5 5v20h20V70z" fill-rule="evenodd"/><path d="M43 6h10v15H43zM44 31h15v10H44zM65 47h30v10H65zM43 64h10v30H43zM65 67h10v12H65zM80 80h15v15H80zM11 45h25v10H11z"/></g></svg>${link('phone','Preview phone journey →','button primary')}<p class="fine gap">Illustrative QR, not a real code.<br>A readable church link accompanies the real QR.</p></section></div>`)}
function demo(){return `${research()}<main id="main" class="public" tabindex="-1"><header class="public-header">${brand()}<nav class="public-nav" aria-label="Public concepts">${link('demo','How it works')}${link('studio','Studio')}${link('phone','Get started ↗','button primary')}</nav></header><section class="demo-intro"><div><p class="eyebrow">WATCH THE WORKFLOW</p><h1>Your teaching.<br><em>A study taking shape.</em></h1></div><p>Import into a shared library. Compose and ask side by side. Apply only what you choose.</p></section><div class="home-tabs" role="tablist" aria-label="Homepage product introduction"><button role="tab" data-hometab="overview" aria-selected="false" tabindex="-1" aria-controls="home-content">Why Rooted</button><button role="tab" data-hometab="ai" aria-selected="true" tabindex="0" aria-controls="home-content">AI in Studio</button><button role="tab" data-hometab="members" aria-selected="false" tabindex="-1" aria-controls="home-content">For your members</button></div><section id="home-content" role="tabpanel" aria-label="AI in Studio"><div id="alternate-home-panel" hidden></div><div id="ai-home-panel"><div class="video-frame"><video id="workflow-video" autoplay muted playsinline loop preload="auto" poster="media/workflow-poster.png" aria-label="Research prototype workflow recording"><source src="media/studio-workflow.webm" type="video/webm"><track kind="captions" src="media/workflow-captions.vtt" srclang="en" label="English workflow captions" default></video><span class="video-label">LOCAL RESEARCH WORKFLOW RECORDING · SIMULATED EXTRACTION + AI</span><div class="video-fallback" id="video-fallback" hidden><h3 id="fallback-title">Playback needs your choice.</h3><p id="fallback-text">The recording and transcript are ready.</p><button class="primary" data-action="play-video">Play workflow recording</button></div></div><div class="video-controls"><div class="row"><button data-action="pause-video">Pause</button><button data-action="sound-video" aria-pressed="false">Sound off</button><button data-action="captions-video" aria-pressed="true">Captions on</button><button data-action="restart-video">Restart</button></div><p class="fine" id="video-status" role="status">Real local recording. No paid AI or production service.</p></div><details class="demo-transcript"><summary>Read the workflow transcript and recording scope</summary><p>Begin with the channel source library. One Import dialog accepts files, links, pasted text, and planned connections. Names are retained; processing and errors are per item. Select ready sources for context. Compose and ask beside the same editable document. Apply a proposal, Undo, arrange visual elements in Design mode, and preview the logical reading order.</p><p>Encoded from this research UI and fictional actions. Extraction and AI responses are simulations. The recording is silent; sound can be unmuted but adds no invented narration. Reduced motion, data-saving preference, browser policy, or media failure may pause autoplay. The transcript remains available.</p></details></div></section></main>`}
function board(){return `${research()}${header()}<main id="main" class="board" tabindex="-1"><p class="eyebrow">REBUILT AROUND YOUR FOUR CORRECTIONS</p><h1>One place to compose.<br><em>More room for your teaching.</em></h1><p style="max-width:760px">A shared channel library, a flexible Studio, and an actual local workflow video visible on entry. Fictional church data; no production connection.</p><div class="board-grid">${[['01','Channel source library','Names, links, processing, errors, and selected context.','library'],['02','One Import dialog','Files, links, paste, and planned cloud connections.','library','import'],['03','Unified Studio / Compose','Editable content, ribbon, and docked assistant.','studio'],['04','Reading + Design','Flexible geometry and a clear logical reading order.','studio','ready','&mode=design'],['05','Review conversation','Quoted anchor and a fresh review cycle.','review'],['06','Public share deck','Exact rendition approval and member opt-in.','deck'],['07','Actual workflow recording','Muted autoplay with pause, captions, and fallbacks.','demo'],['08','Member phone','Church context, verification, and reading access.','phone'],['09','Immersive reading','The same edited content, in logical order.','preview']].map(([n,t,d,v,s,e])=>`<a href="${href(v,s||'ready',e||'')}"><span class="number">${n} ↗</span><h2>${t}</h2><p>${d}</p></a>`).join('')}</div><div class="note gap">Other states: ${link('library','Empty library','','empty')} · ${link('deck','Stale deck','','stale')} · ${link('phone','Expired code','','expired')} · ${link('phone','Church ambiguity','','ambiguity')} · ${link('demo','Blocked autoplay','','blocked')}</div><p class="fine gap">Heuristic role evaluation, not actual human usability research. All edits remain in this origin’s research session.</p></main>`}
function render(focus=false){app.innerHTML=({board,library,studio,preview,review,deck,phone,reader,share,qr,demo}[view]||board)();document.title=`${({board:'Rebuilt storyboard',library:'Channel source library',studio:'Unified Studio / Compose',demo:'Workflow recording',review:'Review conversation',phone:'Member access',reader:'Member rendition',share:'Optional public sharing',deck:'Public share deck',preview:'Immersive preview',qr:'Church routing'})[view]} · Rooted research`;bind();if(focus)document.querySelector('main')?.focus();if(view==='demo')initVideo();if(view==='library'&&state==='import'){state='ready';const u=new URL(location);u.searchParams.set('state','ready');history.replaceState({},'',u);openImport()}}
function status(t){const e=document.querySelector('#workflow-status');if(e)e.textContent=t;announce(t)}
function transition(s){state=s;const u=new URL(location);u.searchParams.set('state',s);u.searchParams.set('church',church);history.replaceState({},'',u);render(true);scrollTo(0,0)}
function bindCanvas(){document.querySelectorAll('[data-block]').forEach(el=>{el.onclick=()=>{if(selected!==el.dataset.block)selectionRange=null;selected=el.dataset.block;const current=blocks.find(x=>x.id===selected);document.querySelectorAll('[data-place]').forEach(input=>input.value=current[input.dataset.place]||5);document.querySelectorAll('[data-format]').forEach(button=>button.setAttribute('aria-pressed',String(!!current[button.dataset.format])));const outline=document.querySelector('#block-outline');if(outline)outline.value=selected;document.querySelectorAll('[data-block]').forEach(x=>x.classList.toggle('selected',x.dataset.block===selected));document.querySelector('#selection-label').innerHTML=`Selected: <strong>${esc(blocks.find(b=>b.id===selected).title)}</strong> · Reading position ${blocks.findIndex(b=>b.id===selected)+1}`};el.onkeydown=e=>{if(e.target===el&&(e.key==='Enter'||e.key===' ')){e.preventDefault();selected=el.dataset.block;render();document.querySelector(`[data-block="${selected}"]`).focus()}}});document.querySelectorAll('[data-edit]').forEach(el=>{el.onfocus=()=>selected=el.dataset.edit;el.oninput=()=>{const b=blocks.find(b=>b.id===el.dataset.edit);if(!el.dataset.undoCaptured){undo.push(structuredClone(blocks));el.dataset.undoCaptured='yes'}b.text=el.innerText;b.marks=[];persist();document.querySelector('[data-action="undo"]').disabled=false;document.querySelector('#save-state').textContent='Research changes in this browser'};el.onmouseup=()=>{const s=getSelection();if(s.rangeCount&&s.toString()){const r=s.getRangeAt(0),pre=r.cloneRange();pre.selectNodeContents(el);pre.setEnd(r.startContainer,r.startOffset);selectionRange={id:el.dataset.edit,start:pre.toString().length,end:pre.toString().length+s.toString().length};document.querySelector('#selection-label').textContent=`Selected text: “${s.toString().slice(0,35)}” in ${blocks.find(b=>b.id===el.dataset.edit).title}`}}})}
function bindDialog(){document.querySelectorAll('[data-import-kind]').forEach(b=>b.onclick=()=>{importKind=b.dataset.importKind;openImport()});document.querySelectorAll('#import-dialog [data-action]').forEach(b=>b.onclick=()=>act(b.dataset.action));const f=document.querySelector('#file-picker');if(f)f.onchange=()=>addFiles([...f.files]);const drop=document.querySelector('#dropzone');if(drop){drop.ondragover=e=>e.preventDefault();drop.ondrop=e=>{e.preventDefault();addFiles([...e.dataTransfer.files])}}}
function addFiles(files){for(const f of files)sources.push({id:crypto.randomUUID(),name:f.name,type:f.name.split('.').pop().toUpperCase(),status:'error',selected:false,version:'v1',locator:'unprocessed',detail:'Original filename retained. No parser/upload is connected; content was not read or sent.'});saveSources();document.querySelector('#import-dialog').close();render();status('Filenames retained. No real file contents uploaded or parsed.')}
function homeTab(key){const ai=key==='ai';document.querySelector('#ai-home-panel').hidden=!ai;const alt=document.querySelector('#alternate-home-panel');alt.hidden=ai;if(!ai){document.querySelector('#workflow-video').pause();alt.innerHTML='<div class="panel gap"><h2>'+(key==='overview'?'Your church’s teaching. A shared direction.':'A focused place to read and reflect.')+'</h2><p class="gap">Rooted helps carry the message into ordinary life. Choose AI in Studio to see the workflow recording.</p></div>'}document.querySelectorAll('[data-hometab]').forEach(b=>{b.setAttribute('aria-selected',String(b.dataset.hometab===key));b.tabIndex=b.dataset.hometab===key?0:-1});if(ai)initVideo()}
function bind(){document.querySelectorAll('[data-hometab]').forEach((b,i)=>{b.onclick=()=>homeTab(b.dataset.hometab);b.onkeydown=e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const bs=[...document.querySelectorAll('[data-hometab]')],j=e.key==='Home'?0:e.key==='End'?2:(i+(e.key==='ArrowRight'?1:2))%3;homeTab(bs[j].dataset.hometab);bs[j].focus()}}});document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>act(b.dataset.action));document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>{detailId=b.dataset.detail;render();document.querySelector(`[data-detail="${detailId}"]`).focus()});document.querySelectorAll('[data-context]').forEach(c=>c.onchange=()=>{sources.find(s=>s.id===c.dataset.context).selected=c.checked;saveSources();const id=c.dataset.context;render();document.querySelector(`[data-context="${id}"]`).focus();status(`${chosen().length} ready sources selected for the next request. No model call.`)});document.querySelector('#source-search')?.addEventListener('input',e=>document.querySelectorAll('[data-source-row]').forEach(row=>row.hidden=!sources.find(s=>s.id===row.dataset.sourceRow).name.toLowerCase().includes(e.target.value.toLowerCase())));document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;render();document.querySelector(`[data-mode="${mode}"]`).focus()});document.querySelectorAll('[data-format]').forEach(b=>b.onclick=()=>{const t=b.dataset.format;change(()=>{const x=blocks.find(b=>b.id===selected);if(selectionRange?.id===selected){x.marks=[{start:selectionRange.start,end:selectionRange.end,tag:t==='bold'?'strong':'em'}]}else x[t]=!x[t]});render();status('Formatting applied to the text selection, or current block when no text range is selected. Undo is available.')});document.querySelectorAll('[data-align]').forEach(b=>b.onclick=()=>{change(()=>blocks.find(x=>x.id===selected).align=b.dataset.align);render()});document.querySelector('#font-size')?.addEventListener('change',e=>{change(()=>blocks.find(b=>b.id===selected).size=Number(e.target.value));render()});document.querySelectorAll('[data-place]').forEach(input=>input.onchange=()=>{change(()=>blocks.find(b=>b.id===selected)[input.dataset.place]=Math.max(0,Math.min(95,Number(input.value))));document.querySelector('.canvas-stage').innerHTML=editorCanvas();bindCanvas();status('Placement changed; logical reading order stayed the same.')});document.querySelectorAll('[data-slide]').forEach(b=>b.onclick=()=>{slide=Number(b.dataset.slide);document.querySelector('#deck-export').outerHTML=deckCard();document.querySelectorAll('[data-slide]').forEach(x=>x.setAttribute('aria-pressed',String(Number(x.dataset.slide)===slide)))});document.querySelectorAll('[data-phone]').forEach(b=>b.onclick=()=>transition(b.dataset.phone));document.querySelectorAll('[data-church]').forEach(b=>b.onclick=()=>{church=b.dataset.church;const u=new URL(location);u.searchParams.set('church',church);history.replaceState({},'',u);document.querySelectorAll('[data-church]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)))});const c=document.querySelector('#share-consent');if(c)c.onchange=()=>document.querySelector('[data-action="share"]').disabled=!c.checked;document.querySelector('#block-outline')?.addEventListener('change',e=>{selected=e.target.value;selectionRange=null;render();document.querySelector(`[data-block="${selected}"]`).focus()});bindCanvas();document.querySelector('#import-dialog').onclose=()=>document.querySelector('[data-action="import"]')?.focus()}
function act(a){const b=()=>blocks.find(x=>x.id===selected);if(a==='import')openImport();if(a==='close-import')document.querySelector('#import-dialog').close();if(a==='choose-files')document.querySelector('#file-picker').click();if(a==='sample-batch')addSamples();if(a==='add-links'){for(const url of document.querySelector('#link-input').value.split(/\n/).map(x=>x.trim()).filter(Boolean))sources.push({id:crypto.randomUUID(),name:url,url,type:'URL',status:'error',selected:false,version:'v1',locator:'unprocessed',detail:'Actual link text retained. No network fetch runs; provide an authorized source.'});saveSources();document.querySelector('#import-dialog').close();render()}if(a==='add-paste'){const name=document.querySelector('#paste-title').value.trim()||'Untitled pasted source',text=document.querySelector('#paste-text').value;if(!text.trim()){announce('Paste some text first.');return}sources.push({id:crypto.randomUUID(),name,type:'TEXT',status:'ready',selected:false,version:'v1',locator:'pasted text',text,detail:'Local pasted text. No live AI request.'});saveSources();document.querySelector('#import-dialog').close();render()}if(a==='retry-source'){importKind='paste';openImport()}if(a==='apply'){if(['diagram','image','video','chart'].includes(b().kind)){status('Select text for this writing proposal. A visual candidate needs asset review.');return}const t=document.querySelector('#proposal-text').textContent;change(()=>{if(selectionRange?.id===selected)b().text=b().text.slice(0,selectionRange.start)+t+b().text.slice(selectionRange.end);else b().text=t;b().marks=[]});selectionRange=null;render();status('Applied only to the current selection. Undo restores the previous draft.')}if(a==='undo'&&undo.length){blocks=undo.pop();persist();selectionRange=null;render();status('Last document change undone.')}if(a==='insert'){const kind=document.querySelector('#insert-kind').value;change(()=>{const id='block-'+crypto.randomUUID().slice(0,7);blocks.splice(blocks.findIndex(x=>x.id===selected)+1,0,{id,kind,title:kind[0].toUpperCase()+kind.slice(1),text:kind==='paragraph'?'Write your church’s teaching here.':kind==='columns'?'A passage to read.':'Illustrative '+kind+'; review the candidate and add an accurate text alternative.',x:10,y:35,w:80});selected=id});render();status('Research block inserted. No generated asset or backend request.')}if(a==='up'||a==='down'){const i=blocks.findIndex(x=>x.id===selected),j=a==='up'?i-1:i+1;if(j>=0&&j<blocks.length){change(()=>[blocks[i],blocks[j]]=[blocks[j],blocks[i]]);render();status('Logical order changed in both previews; geometry stays independent.')}}if(a==='front'){change(()=>b().z=50);render();status('Selected element brought forward. Reading order did not change.')}if(a==='crop')status('Image crop and grouping are planned affordances; no crop operation is claimed by this prototype.');if(a==='describe')status(`Text alternative for ${b().title}: ${b().text}`);if(a==='save'){persist();dirty=false;document.querySelector('#save-state').textContent='Saved in research session';status('Saved locally; production unchanged.')}if(a==='ask')status('Sample response shown beside the selection. No AI or paid generation.');if(a==='review-reply')document.querySelector('#review-status').textContent='Sample reply recorded. Original r11 request stays open; r12 is not approved.';if(a==='review-resubmit')document.querySelector('#review-status').textContent='Proposed fresh cycle targets r12 even if unchanged. Current backend defect remains visible; no request or notification sent.';if(a==='approve-deck')document.querySelector('#deck-status').textContent='Sample approval: exact deck v3, approved r10, cards/caption/destination. Nothing published.';if(a==='alternate')document.querySelector('#phone-status').textContent='An alternate verified provider retains this church. Authentication is not started here.';if(a==='share'){document.querySelector('#share-options').hidden=false;document.querySelector('#share-status').textContent='You chose sharing options. Nothing posted.'}if(a==='copy'||a==='download')document.querySelector('#share-status').textContent=a==='copy'?'Sample public link: rooted.example/grace/abide. No clipboard access.':'Research PNGs are in exports/. No private study data.';if(a.endsWith('-video'))videoAction(a)}
async function initVideo(){const v=document.querySelector('#workflow-video'),f=document.querySelector('#video-fallback'),m=document.querySelector('#video-status');v.muted=true;v.playsInline=true;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches,saveData=navigator.connection?.saveData;const reveal=(title,text)=>{f.hidden=false;document.querySelector('#fallback-title').textContent=title;document.querySelector('#fallback-text').textContent=text};v.querySelector('source')?.addEventListener('error',()=>{reveal('Recording could not load.','The poster and transcript remain available. Retry if you choose.');m.textContent='Media unavailable; transcript remains readable.'});setTimeout(()=>{if(v.readyState<2&&f.hidden){reveal('Recording is taking longer to load.','Use the transcript below or choose playback when ready.');m.textContent='Media readiness timeout; readable fallback available.'}},2200);v.addEventListener('playing',()=>{f.hidden=true;m.textContent='Playing a real local research workflow recording · muted by default.';document.querySelector('[data-action="pause-video"]').textContent='Pause'});v.addEventListener('timeupdate',()=>v.dataset.progress=v.currentTime.toFixed(2));v.addEventListener('error',()=>{reveal('Recording could not load.','Use the transcript below or retry playback.');m.textContent='Media unavailable; transcript remains readable.'});if(reduced||saveData||state==='blocked'){v.autoplay=false;v.pause();reveal(reduced?'Motion is paused for your preference.':saveData?'Data-saving preference respected.':'Autoplay-blocked example.','Start the recording when you choose, or read the transcript.');m.textContent=reduced?'Reduced motion: no automatic playback.':'Autoplay exception; explicit playback available.';document.querySelector('[data-action="pause-video"]').textContent='Play';return}try{await v.play()}catch(error){if(v.error||error.name==='NotSupportedError'){reveal('Recording could not load.','Use the poster and transcript below, or retry playback.');m.textContent='Media unavailable; transcript remains readable.'}else{reveal('Your browser paused autoplay.','The muted recording may need a click. Transcript is available.');m.textContent='Autoplay rejected; explicit play fallback visible.'}}}
async function videoAction(a){const v=document.querySelector('#workflow-video');if(a==='play-video'||a==='pause-video'){if(v.paused){try{await v.play()}catch{document.querySelector('#video-status').textContent='Playback unavailable; read the transcript.'}}else{v.pause();document.querySelector('[data-action="pause-video"]').textContent='Resume';document.querySelector('#video-status').textContent='Recording paused.'}}if(a==='sound-video'){v.muted=!v.muted;const b=document.querySelector('[data-action="sound-video"]');b.textContent=v.muted?'Sound off':'Sound on · silent recording';b.setAttribute('aria-pressed',String(!v.muted))}if(a==='captions-video'){const t=v.textTracks[0],show=!t||t.mode!=='showing';if(t)t.mode=show?'showing':'hidden';const b=document.querySelector('[data-action="captions-video"]');b.textContent=show?'Captions on':'Captions off';b.setAttribute('aria-pressed',String(show))}if(a==='restart-video'){v.currentTime=0;await v.play().catch(()=>{})}}
render();
if(location.hash)requestAnimationFrame(()=>{const target=document.getElementById(location.hash.slice(1));if(target){target.focus();target.scrollIntoView({block:'start'})}});
